package ai.finsight.forecast;

import ai.finsight.recurring.*;import ai.finsight.transaction.*;import ai.finsight.user.UserRepository;
import org.springframework.jdbc.core.namedparam.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.math.*;import java.time.*;import java.util.*;

@Service
public class ForecastService {
 public record MonthForecast(String month,BigDecimal projectedIncome,BigDecimal projectedExpenses,BigDecimal projectedSavings,BigDecimal expectedClosingCashBalance){}
 public record Commitment(String title,String category,BigDecimal amount,String type,LocalDate dueDate,String frequency){}
 public record Forecast(List<MonthForecast> months,List<Commitment> upcomingCommitments,int historicalMonthsUsed,String confidence,BigDecimal averageHistoricalIncome,BigDecimal averageHistoricalExpenses,BigDecimal recurringMonthlyIncome,BigDecimal recurringMonthlyExpenses,List<String> assumptions){}
 private final UserRepository users;private final TransactionRepository transactions;private final RecurringTransactionRepository recurring;private final NamedParameterJdbcTemplate jdbc;
 public ForecastService(UserRepository u,TransactionRepository t,RecurringTransactionRepository r,NamedParameterJdbcTemplate j){users=u;transactions=t;recurring=r;jdbc=j;}
 @Transactional(readOnly=true) public Forecast forecast(String email){UUID owner=users.findByEmailIgnoreCase(email).orElseThrow().getId();YearMonth current=YearMonth.now();LocalDate today=LocalDate.now();BigDecimal incomeTotal=BigDecimal.ZERO,expenseTotal=BigDecimal.ZERO;int monthsWithData=0;for(int i=3;i>=1;i--){YearMonth m=current.minusMonths(i);LocalDate from=m.atDay(1),to=m.plusMonths(1).atDay(1);BigDecimal income=transactions.sumForOwnerAndPeriod(owner,from,to,FinancialTransaction.Direction.INCOME);BigDecimal expense=transactions.sumForOwnerAndPeriod(owner,from,to,FinancialTransaction.Direction.EXPENSE);incomeTotal=incomeTotal.add(income);expenseTotal=expenseTotal.add(expense);if(income.signum()!=0||expense.signum()!=0)monthsWithData++;}BigDecimal historicalIncome=money(incomeTotal.divide(BigDecimal.valueOf(3),2,RoundingMode.HALF_UP)),historicalExpenses=money(expenseTotal.divide(BigDecimal.valueOf(3),2,RoundingMode.HALF_UP));BigDecimal recurringIncome=BigDecimal.ZERO,recurringExpenses=BigDecimal.ZERO;List<RecurringTransaction> active=recurring.findAllByUserIdOrderByNextDueDateAsc(owner).stream().filter(RecurringTransaction::isActive).filter(r->r.getEndDate()==null||!r.getEndDate().isBefore(today)).toList();for(RecurringTransaction r:active){BigDecimal monthly=monthlyized(r.getAmount(),r.getFrequency());if(r.getType()==RecurringTransaction.Type.INCOME)recurringIncome=recurringIncome.add(monthly);else recurringExpenses=recurringExpenses.add(monthly);}recurringIncome=money(recurringIncome);recurringExpenses=money(recurringExpenses);BigDecimal projectedIncome=historicalIncome.max(recurringIncome),projectedExpenses=historicalExpenses.max(recurringExpenses);BigDecimal cash=jdbc.queryForObject("SELECT COALESCE(SUM(current_value),0) FROM financial_asset WHERE user_id=:user AND category IN ('Cash','Bank Account')",new MapSqlParameterSource("user",owner),BigDecimal.class);cash=money(cash);BigDecimal savings=money(projectedIncome.subtract(projectedExpenses));List<MonthForecast> forecast=new ArrayList<>();BigDecimal closing=cash;for(int i=0;i<3;i++){YearMonth month=current.plusMonths(i);closing=money(closing.add(savings));forecast.add(new MonthForecast(month.toString(),projectedIncome,projectedExpenses,savings,closing));}List<Commitment> commitments=new ArrayList<>();LocalDate through=current.plusMonths(3).atDay(1);for(RecurringTransaction r:active){if(r.getType()!=RecurringTransaction.Type.EXPENSE)continue;LocalDate due=r.getNextDueDate();while(due.isBefore(through)&&(r.getEndDate()==null||!due.isAfter(r.getEndDate()))){if(!due.isBefore(today))commitments.add(new Commitment(r.getTitle(),r.getCategory(),money(r.getAmount()),r.getType().name(),due,r.getFrequency().name()));due=advance(due,r.getFrequency());}}commitments.sort(Comparator.comparing(Commitment::dueDate));String confidence=monthsWithData>=3?"BASELINE":monthsWithData>0?"LIMITED":active.isEmpty()?"INSUFFICIENT_DATA":"SCHEDULE_ONLY";return new Forecast(List.copyOf(forecast),List.copyOf(commitments),monthsWithData,confidence,historicalIncome,historicalExpenses,recurringIncome,recurringExpenses,List.of("Historical baseline is the average of the last three complete calendar months; empty months count as zero.","Recurring monthly equivalents are a floor, not added on top of the historical average, to reduce double-counting of scheduled items already present in transaction history.","Daily, weekly, monthly, and yearly recurrence values are normalized to 30 days, 52/12 weeks, 1 month, and 1/12 year.","Closing cash starts from user-entered Cash and Bank Account asset values and adds projected monthly savings; no transfers, returns, or unrecorded transactions are assumed.","Each month is a projection, not a guaranteed outcome."));}
 private BigDecimal monthlyized(BigDecimal amount,RecurringTransaction.Frequency f){return switch(f){case DAILY->amount.multiply(BigDecimal.valueOf(30));case WEEKLY->amount.multiply(BigDecimal.valueOf(52)).divide(BigDecimal.valueOf(12),2,RoundingMode.HALF_UP);case MONTHLY->amount;case YEARLY->amount.divide(BigDecimal.valueOf(12),2,RoundingMode.HALF_UP);};}
 private LocalDate advance(LocalDate d,RecurringTransaction.Frequency f){return switch(f){case DAILY->d.plusDays(1);case WEEKLY->d.plusWeeks(1);case MONTHLY->d.plusMonths(1);case YEARLY->d.plusYears(1);};}
 private BigDecimal money(BigDecimal v){return v.setScale(2,RoundingMode.HALF_UP);}
}
